    ('2021', '2021', 'Full-stack Developer - Freelance', 'Vastovers Stemordz Ltd', '["Developed a complete online store for Vastover Stemordz Ltd, a pharmaceutical company in Abuja, Nigeria.", "Upgraded their outdated system to a modern e-commerce platform.", "Built the entire app from scratch, including the front-end and back-end.", "Made sure the old and new systems could work together smoothly.", "Created user-friendly features and designs to make shopping easier.", "Worked closely with the company to understand their needs and meet their requirements.", "Ensured the website was secure and protected customer information.", "Tested everything thoroughly to fix any problems and make it run smoothly.", "Provided ongoing support and maintenance to keep the website running well.", "Helped Vastover Stemordz Ltd grow their online sales and reach more customers in the pharmaceutical industry."]', '["React.js", "Web Development", "Back-End Web Development", "Python (Programming Language)", "Representational State Transfer (REST)", "Front-End Development", "E-commerce", "Web Design", "Web Application Development", "PostgreSQL", "Redux.js", "Flask", "Databases"]', 6),
    ('2021', '2021', 'NYSC Attaché - Support Personnel', 'Inlaks Nigeria', '["At INLAKS Ltd., the sole distributor of Temenos T24 in Sub-Saharan Africa, I provided support for the core banking sector on a project with CBN. I gained hands-on experience with T24, running batch scripts, subroutines, and database queries to improve performance and reduce redundancy. Working extensively with the terminal, I deepened my understanding of core banking concepts and system limitations, enhancing my problem-solving skills and ability to work under pressure. This experience equipped me with the technical expertise to contribute effectively to banking and financial technology solutions."]', '["cmd", "Bash", "jBase", "SQL", "MySQL", "window server", "Linux", "Temenos T24", "Core Banking", "Banking", "Financial Technology", "Batch Processing", "Database Management", "System Administration"]', 7),
    ('2019', '2019', 'Software Developer Intern', 'Pyrich Group Limited', '["I developed and enhanced a full-stack web application for a government agency to manage visitor information and streamline operations. My role involved building core functionalities, improving existing systems, and troubleshooting bugs to enhance system reliability. This experience strengthened my problem-solving skills, attention to detail, and understanding of quality assurance in real-world software development."]', '["Node.js", "React.js", "Web Design", "Web Development", "Express.js", "Back-End Web Development", "Databases", "Redux.js", "Knex.js", "Representational State Transfer (REST)", "PostgreSQL", "Front-End Development", "SaaS Development"]', 8);
